<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Item } from './api'
import type { PartySession } from './usePartySession'
import PartyIcon from './PartyIcon.vue'
import SongArtwork from './SongArtwork.vue'
const props = defineProps<{ session: PartySession }>()
const emit = defineEmits<{ priority: [item: Item]; remove: [item: Item]; shuffle: []; detail: [item: Item] }>()
const mine = ref(false)
const snapshot = computed(() => props.session.state.snapshot)
const items = computed(() => props.session.waiting.value.map((item, index) => ({ ...item, position: index + 1 })).filter(item => !mine.value || item.ownerId === snapshot.value?.actorId))
const disabled = computed(() => props.session.state.busy || !props.session.state.online || !!props.session.state.pending || snapshot.value?.status !== 'ACTIVE')
</script>
<template><section><div class="page-intro"><h1>大家的已点</h1><p>每人一首轮流唱，各自的歌按点歌顺序。</p></div><div v-if="session.current.value && !['ENDED','IDLE','ERROR'].includes(snapshot?.playback?.state ?? 'IDLE')" class="current-queue"><span class="pill">{{ snapshot?.playback?.state === 'PAUSED' ? '已暂停' : '正在唱' }}</span><button class="song-open" @click="emit('detail', session.current.value)"><SongArtwork :path="session.current.value.song.coverPath" :token="session.state.credential?.token" /><span class="song-meta"><strong class="song-title">{{ session.current.value.song.title }}</strong><span class="song-artist">{{ session.current.value.ownerName }}点的</span></span></button></div><div class="queue-tools"><div class="segmented"><button :class="{ active: !mine }" @click="mine = false">全部 {{ session.waiting.value.length }}</button><button :class="{ active: mine }" @click="mine = true">我点的</button></div><button class="text-button shuffle" :disabled="disabled || snapshot?.queuePolicy !== 'FAIR' || session.waiting.value.length < 2" @click="emit('shuffle')"><PartyIcon name="shuffle" />公平打乱</button></div><p v-if="snapshot?.queuePolicy !== 'FAIR'" class="helper">电视升级后，启用按人轮流。</p><p v-else class="helper queue-helper">公平打乱只调整亲友的轮转顺序；插队只占一个下一首优先位。</p><h2 class="next-title">接下来</h2><div v-if="!items.length" class="empty-state"><PartyIcon name="queue" /><h3>{{ mine ? '还没有你点的待唱歌曲' : '下一首，等你来点' }}</h3><p>去曲库挑一首想唱的歌吧。</p></div><article v-for="item in items" :key="item.id" class="queue-row" :class="{ prioritized: item.priority }"><span class="queue-number">{{ item.position }}</span><button class="song-open" @click="emit('detail', item)"><SongArtwork :path="item.song.coverPath" :token="session.state.credential?.token" /><span class="song-meta"><strong class="song-title">{{ item.song.title }}</strong><span class="song-artist">{{ item.ownerName }}点的 <span v-if="item.priority" class="priority-label">下一首优先</span></span></span></button><div class="queue-actions"><button :disabled="disabled || snapshot?.queuePolicy !== 'FAIR'" @click="emit('priority', item)">{{ item.priority ? '取消插队' : '插队' }}</button><button v-if="snapshot?.host || item.ownerId === snapshot?.actorId" class="remove" :disabled="disabled" @click="emit('remove', item)">撤歌</button></div></article></section></template>
